    pub fn read()->Self{
        let mut t=Self{
            routers:BTreeMap::new(),
            links:Vec::new(),
            initial:Vec::new()
        };
        for line in fs::read_to_string("input/topology.txt").unwrap().lines(){
            let a:Vec<_>=line.split(' ').collect();
            match a[0]{
                "AS"=>{
                    t.routers.insert(a[1].parse().unwrap(),address(a[2]));
                },"LINK"=>t.links.push(Link{
                    name:a[1].into(),
                    a:a[2].parse().unwrap(),
                    b:a[3].parse().unwrap(),
                    peer:a[4]=="P2P",
                    delay:a[5].parse().unwrap(),
                    mrai:a[6].parse().unwrap(),
                    up:true,
                    downs:0
                }),_=>t.initial.push((a[1].parse().unwrap(),Prefix::parse(a[2]),a[3].into(),a[4..].iter().map(|v|crate::policy::community(v)).collect()))
            }
        }
        t
    }
    pub fn read()->Self{
        let mut p=Self{
            lists:BTreeMap::new(),
            rules:Vec::new()
        };
        for line in fs::read_to_string("input/policies.txt").unwrap().lines(){
            let a:Vec<_>=line.split(' ').collect();
            if a[0]=="PLIST"{
                let prefix=Prefix::parse(a[3]);
                let(mut low,mut high)=(prefix.length,prefix.length);
                let mut i=4;
                while i<a.len(){
                    if a[i]=="GE"{
                        low=a[i+1].parse().unwrap();
                        high=32;
                    }else{
                        high=a[i+1].parse().unwrap();
                    }
                    i+=2;
                }
                p.lists.entry(a[1].into()).or_default().push(Entry{
                    permit:a[2]=="PERMIT",
                    prefix,
                    low,
                    high
                });
            }else{
                let mut r=Rule{
                    name:a[1].into(),
                    on:a[2]=="ON",
                    owner:a[3].parse().unwrap(),
                    import:a[4]=="IMPORT",
                    target:a[5].into(),
                    conditions:Vec::new(),
                    actions:Vec::new(),
                    hits:0
                };
                let mut i=6;
                while a[i]!="THEN"{
                    r.conditions.push(match a[i]{
                        "PREFIX"=>Condition::Prefix(a[i+1].into()),"CONTAINS"=>Condition::Contains(a[i+1].parse().unwrap()),"ORIGINAS"=>Condition::Origin(a[i+1].parse().unwrap()),"LENGTH"=>{
                            let(x,y)=a[i+1].split_once('-').unwrap();
                            Condition::Length(x.parse().unwrap(),y.parse().unwrap())
                        },_=>Condition::Community(community(a[i+1]))
                    });
                    i+=2;
                }
                i+=1;
                while i<a.len(){
                    let action=match a[i]{
                        "DENY"=>Action::Deny,"ALLOW"=>Action::Allow,"LOCALPREF"=>Action::Local(a[i+1].parse().unwrap()),"MED"=>Action::Med(a[i+1].parse().unwrap()),"PREPEND"=>Action::Prepend(a[i+1].parse().unwrap()),"ADD"=>Action::Add(community(a[i+1])),_=>Action::Remove(community(a[i+1]))
                    };
                    i+=if matches!(action,Action::Deny|Action::Allow){
                        1
                    }else{
                        2
                    };
                    r.actions.push(action);
                }
                p.rules.push(r);
            }
        }
        p
    }
    pub fn applied(&self,import:bool,x:Asn,link:&Link,p:Prefix,path:&[Asn],comm:&Communities)->Option<usize>{
        self.rules.iter().position(|r|r.on&&r.owner==x&&r.import==import&&(r.target=="*"||r.target==link.name||r.target==link.other(x).to_string())&&r.conditions.iter().all(|c|match c{
            Condition::Prefix(n)=>self.permitted(n,p),Condition::Contains(a)=>path.contains(a),Condition::Origin(a)=>path.last().copied().unwrap_or(x)==*a,Condition::Length(lo,hi)=>*lo<=path.len()&&path.len()<=*hi,Condition::Community(c)=>comm.contains(c)
        }))
    }
    pub fn send(&mut self,time:i64,delay:i64,sender:Asn,receiver:Asn,link:usize,prefix:Prefix,content:Option<Attribute>)->Message{
        self.serial+=1;
        let m=Message{
            serial:self.serial,
            sender,
            receiver,
            link,
            prefix,
            content,
            arrival:time+delay
        };
        self.messages.insert((m.arrival,receiver,sender,m.serial),m.clone());
        m
    }
pub fn events()->Vec<Event>{
    let mut all=vec![Event{
        time:0,text:"INITIAL".into(),fields:vec!["INITIAL".into()],kind:"INITIAL".into()
    }];
    for line in fs::read_to_string("input/events.txt").unwrap().lines(){
        let(t,text)=line.split_once(' ').unwrap();
        let fields:Vec<String>=text.split(' ').map(str::to_string).collect();
        let kind=if fields[0]=="LINK"||fields[0]=="POLICY"{
            fields[..2].join("_")
        }else{
            fields[0].clone()
        };
        all.push(Event{
            time:t.parse().unwrap(),
            text:text.into(),
            fields,
            kind
        });
    }
    all
}
